def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    color_for_side = {3: 8, 5: 4, 7: 3}

    for top in range(h):
        for bottom in range(top + 2, h):
            for left in range(w):
                for right in range(left + 2, w):
                    if not all(grid[top][c] == 2 and grid[bottom][c] == 2
                               for c in range(left, right + 1)):
                        continue
                    if not all(grid[r][left] == 2 and grid[r][right] == 2
                               for r in range(top, bottom + 1)):
                        continue

                    ih, iw = bottom - top - 1, right - left - 1
                    if ih != iw or ih not in color_for_side:
                        continue
                    if not any(grid[r][c] == 2
                               for r in range(top + 1, bottom)
                               for c in range(left + 1, right)):
                        continue

                    color = color_for_side[ih]
                    for r in range(top + 1, bottom):
                        for c in range(left + 1, right):
                            if grid[r][c] == 0:
                                out[r][c] = color
    return out
